const $=id=>document.getElementById(id);let settings={connectors:[],people:[],response_style:{},service_catalog:[]},currentTicketFilter='all',currentKnowledgeFilter='',currentIssueFilter='all';
const ticketState={page:1,pageSize:50,total:0,items:[],quick:'all',selected:new Set(),currentId:'',loading:false};
let toastTimer;
function toast(message,type='info',duration){const el=$('toast');clearTimeout(toastTimer);el.textContent=String(message||'操作完成');el.className=`show ${type}`;toastTimer=setTimeout(()=>{el.className=''},duration||(type==='error'?7000:3200))}
async function api(url,options={}){let response;try{response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}})}catch(error){throw new Error(`网络连接失败：${error.message||'请检查后台是否运行'}`)}const text=await response.text();let data={};if(text){try{data=JSON.parse(text)}catch(_){const error=new Error(response.ok?'服务器响应格式无效':`服务器返回了无法识别的错误（HTTP ${response.status}）`);error.status=response.status;throw error}}if(!response.ok){const suffix=data.error_id?`（${data.error_id}）`:'';const error=new Error((data.message||`请求失败，HTTP ${response.status}`)+suffix);error.status=response.status;throw error}return data}
function activateView(view,title){document.querySelectorAll('.nav,.view').forEach(x=>x.classList.remove('active'));const nav=document.querySelector(`.nav[data-view="${view}"]`);if(nav)nav.classList.add('active');const panel=$(view);if(panel)panel.classList.add('active');$('page-title').textContent=title||(nav?nav.textContent:'管理中心');if(typeof window.onConsoleViewActivated==='function')window.onConsoleViewActivated(view,title)}
document.querySelectorAll('.nav').forEach(btn=>btn.onclick=()=>activateView(btn.dataset.view,btn.textContent));
async function loadOverview(){const d=await api('/api/overview');$('version').textContent=d.version;$('message-count').textContent=d.status.message_count;$('session-count').textContent=d.status.expert_sessions;$('connector-count').textContent=d.connector_count;$('people-count').textContent=d.people_count;$('runtime-label').textContent=d.status.stream_connected?'机器人运行中':'后台已启动';const detail=d.status.ima_health_detail||'',items=[['钉钉 Stream',d.status.stream_connected,d.status.stream_connected?'已连接':'未连接'],['IMA 连接',d.status.ima_connected,d.status.ima_connected?'连接正常':detail||'连接失败'],['知识检索',d.status.ima_search_ok,d.status.ima_search_ok?'检索正常':detail||'不可用'],['AI 知识来源',d.status.ima_content_available,d.status.ima_content_available?'正文可用':detail||'无可用正文'],['LLM API',d.status.llm_connected,d.status.llm_connected?'已连接':'未连接'],['钉钉 OpenAPI',d.status.dtalk_connected,d.status.dtalk_connected?'已连接':'未连接']];$('health-grid').innerHTML=items.map(([n,ok,label])=>`<div class="health"><b>${n}</b><span class="${ok?'ok':''}">${ok?'●':'○'} ${esc(label)}</span></div>`).join('')}

async function shutdownService(){if(!confirm('确定关闭 OpsPilot 服务？关闭后机器人和管理后台都会停止，需要重新启动程序才能恢复。'))return;const button=$('shutdown-service'),pill=document.querySelector('.status-pill');button.disabled=true;button.textContent='正在关闭';pill?.classList.add('stopping');$('runtime-label').textContent='正在安全关闭';try{await api('/api/runtime/shutdown',{method:'POST',body:'{}'});let attempts=0,failures=0;const probe=setInterval(async()=>{attempts++;try{const response=await fetch('/api/overview',{cache:'no-store'});failures=response.ok?0:failures+1}catch(_){failures++}if(failures>=2){clearInterval(probe);pill?.classList.remove('stopping');pill?.classList.add('stopped');$('runtime-label').textContent='服务已关闭';button.textContent='服务已关闭'}else if(attempts>=25){clearInterval(probe);pill?.classList.remove('stopping');$('runtime-label').textContent='关闭状态待确认';button.textContent='请查看控制台';toast('服务未在预期时间内退出，请查看控制台状态','error')}} ,400)}catch(e){button.disabled=false;button.textContent='关闭服务';pill?.classList.remove('stopping');toast(e.message,'error')}}
async function loadLlm(){const d=await api('/api/llm');$('llm-enabled').checked=!!d.enabled;$('llm-url').value=d.base_url||'';$('llm-path').value=d.chat_completions_path||'/v1/chat/completions';$('llm-model').value=d.model||'';$('llm-temperature').value=d.temperature??0.3;$('llm-max-tokens').value=d.max_tokens??1024;$('llm-timeout').value=d.timeout??30;$('llm-mask').textContent=d.has_api_key?`当前密钥：${d.api_key_masked}`:'尚未设置密钥';if(typeof detectAiProvider==='function'){$('llm-provider').value=d.provider||detectAiProvider(d.base_url||'');$('llm-key').dataset.provider=$('llm-provider').value}}
