function renderPeople(){$('people-list').innerHTML=settings.people.length?settings.people.map((p,i)=>`<article class="item-card"><div class="item-head"><div><h3>${esc(p.name||'未命名')}</h3><p>${esc(p.department||'未设置部门')}</p></div><button class="danger" onclick="removePerson(${i})">删除</button></div><div class="inline-fields"><label>姓名<input value="${esc(p.name||'')}" onchange="settings.people[${i}].name=this.value"></label><label>钉钉 Staff ID<input value="${esc(p.staff_id||'')}" onchange="settings.people[${i}].staff_id=this.value"></label><label>部门<input value="${esc(p.department||'')}" onchange="settings.people[${i}].department=this.value"></label><label>角色<input list="people-role-options" value="${esc(p.role||'运维人员')}" placeholder="运维人员 / 工单管理员" onchange="settings.people[${i}].role=this.value"></label></div><label>擅长领域<input value="${esc(p.skills||'')}" onchange="settings.people[${i}].skills=this.value" placeholder="网络、服务器、ERP"></label><button class="primary" onclick="saveSection('people')">保存</button></article>`).join(''):'<div class="form-panel">尚未添加服务人员。添加后可用于工单自动派发；需要初始化管理员时，请填写稳定 Staff ID 并选择“工单管理员”。</div>'}
