function renderConnectors(){
  const typeLabels={http:'企业 HTTP 服务',dingtalk:'钉钉',ima:'IMA 知识库'};
  $('connector-list').innerHTML=settings.connectors.map((c,i)=>`<article class="item-card"><div class="item-head"><div><h3>${esc(c.name)}</h3><p>${esc(typeLabels[c.type]||c.type)} · ${c.enabled?'已启用':'已停用'}</p></div><button class="danger" onclick="removeConnector(${i})">删除</button></div><div class="inline-fields"><label>名称<input value="${esc(c.name)}" onchange="settings.connectors[${i}].name=this.value"></label><label>类型<select onchange="settings.connectors[${i}].type=this.value;renderConnectors()"><option value="http" ${c.type==='http'?'selected':''}>企业 HTTP 服务</option><option value="dingtalk" ${c.type==='dingtalk'?'selected':''}>钉钉</option><option value="ima" ${c.type==='ima'?'selected':''}>IMA 知识库</option></select></label></div>${c.type==='http'?`<label>服务地址<input value="${esc(c.url||'')}" onchange="settings.connectors[${i}].url=this.value" placeholder="https://service.example/api"></label><div class="inline-fields advanced-setting"><label>请求方法<select onchange="settings.connectors[${i}].method=this.value"><option>GET</option><option ${c.method==='POST'?'selected':''}>POST</option><option ${c.method==='PUT'?'selected':''}>PUT</option><option ${c.method==='PATCH'?'selected':''}>PATCH</option></select></label><label>认证方式<select onchange="settings.connectors[${i}].auth_type=this.value"><option value="none">无</option><option value="bearer" ${c.auth_type==='bearer'?'selected':''}>Bearer Token</option><option value="api_key" ${c.auth_type==='api_key'?'selected':''}>API Key</option></select></label></div><label class="advanced-setting">认证密钥<input type="password" value="${esc(c.auth_value||'')}" onchange="settings.connectors[${i}].auth_value=this.value"></label><label class="advanced-setting">Headers（JSON）<textarea onchange="settings.connectors[${i}].headers=this.value">${esc(typeof c.headers==='string'?c.headers:JSON.stringify(c.headers||{}))}</textarea></label><label class="advanced-setting">请求体模板（JSON）<textarea onchange="settings.connectors[${i}].body_template=this.value" placeholder='{"query":"{{input}}"}'>${esc(c.body_template||'')}</textarea></label><label class="advanced-setting">响应字段映射（每行 名称=路径）<textarea onchange="settings.connectors[${i}].response_mapping=this.value" placeholder="状态=data.status">${esc(typeof c.response_mapping==='string'?c.response_mapping:'')}</textarea></label>`:''}<label class="switch-row compact">启用<input type="checkbox" ${c.enabled?'checked':''} onchange="settings.connectors[${i}].enabled=this.checked"><span class="switch"></span></label><div class="item-actions"><button class="secondary" onclick="testConnector(${i})">测试连接</button><button class="primary" onclick="saveSection('connectors')">保存</button></div></article>`).join('')||'<div class="form-panel">尚未添加连接器。点击“添加连接器”，填写名称和服务地址即可开始。</div>'
}
