const modelProviderPresets={deepseek:{name:'DeepSeek',base_url:'https://api.deepseek.com',model:'deepseek-chat'},openai:{name:'OpenAI 兼容',base_url:'https://api.openai.com',model:''},ollama:{name:'本地 Ollama',base_url:'http://127.0.0.1:11434',model:''},custom:{name:'其它兼容服务',base_url:'',model:''}};
function applyModelPreset(i,provider){const m=modelState.models[i],preset=modelProviderPresets[provider]||modelProviderPresets.custom;m.provider=provider;m.api_key='';m.base_url=preset.base_url;m.chat_completions_path='/v1/chat/completions';if(preset.model)m.model=preset.model;renderModels()}
function renderModels(){modelState.routing=modelState.routing||{};const opts='<option value="">使用默认 API</option>'+modelState.models.map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.model)}</option>`).join('');['general','ticket','vision','fallback'].forEach(r=>{const el=$('route-'+r);el.innerHTML=opts;el.value=modelState.routing[r]||''});const fallbackOrder=Array.isArray(modelState.routing.fallback_order)?modelState.routing.fallback_order:[];$('fallback-order-list').innerHTML=modelState.models.filter(m=>m.enabled!==false).map(m=>`<label class="switch-row compact">${esc(m.name||m.model||'未命名 API')}<input type="checkbox" data-fallback-id="${esc(m.id)}" ${fallbackOrder.includes(m.id)?'checked':''}><span class="switch"></span></label>`).join('')||'<small class="field-help">添加并启用 API 后，可在这里设置后续备用顺序。</small>';$('model-list').innerHTML=modelState.models.map((m,i)=>`<article class="item-card"><div class="item-head"><div><h3>${esc(m.name||'未命名 API')}</h3><p>${esc(m.model||'尚未填写模型')} · ${m.enabled!==false?'已启用':'已停用'}</p></div><button class="danger" onclick="removeModel(${i})">删除</button></div><div class="inline-fields"><label>配置名称<input value="${esc(m.name||'')}" onchange="modelState.models[${i}].name=this.value"></label><label>API 服务<select onchange="applyModelPreset(${i},this.value)">${Object.entries(modelProviderPresets).map(([value,p])=>`<option value="${value}" ${String(m.provider||'custom')===value?'selected':''}>${p.name}</option>`).join('')}</select></label><label>模型名称<input value="${esc(m.model||'')}" onchange="modelState.models[${i}].model=this.value"></label></div><label>Base URL<input value="${esc(m.base_url||'')}" onchange="modelState.models[${i}].base_url=this.value" placeholder="https://api.example.com"></label><div class="inline-fields"><label>接口路径<input value="${esc(m.chat_completions_path||'/v1/chat/completions')}" onchange="modelState.models[${i}].chat_completions_path=this.value"></label><label>独立 API Key<input type="password" placeholder="${esc(m.api_key_masked||((m.provider==='ollama')?'本地服务通常无需密钥':'请输入此 API 的密钥'))}" onchange="modelState.models[${i}].api_key=this.value"></label></div><div class="inline-fields advanced-setting"><label>Temperature<input type="number" min="0" max="2" step="0.1" value="${esc(m.temperature??0.3)}" onchange="modelState.models[${i}].temperature=Number(this.value)"></label><label>最大 Token<input type="number" min="64" value="${esc(m.max_tokens??1024)}" onchange="modelState.models[${i}].max_tokens=Number(this.value)"></label><label>超时（秒）<input type="number" min="1" value="${esc(m.timeout??30)}" onchange="modelState.models[${i}].timeout=Number(this.value)"></label></div><label class="switch-row compact">启用<input type="checkbox" ${m.enabled!==false?'checked':''} onchange="modelState.models[${i}].enabled=this.checked;renderModels()"><span class="switch"></span></label><div class="item-actions"><button class="secondary" onclick="testModel(${i})">测试连接</button><button class="primary" onclick="saveModels()">保存</button></div></article>`).join('')||'<div class="form-panel">尚未添加其它 API。点击右上角“添加 API”开始配置。</div>'}
function addModel(){modelState.models.push({id:crypto.randomUUID(),name:'新 API',provider:'deepseek',model:'deepseek-chat',base_url:'https://api.deepseek.com',chat_completions_path:'/v1/chat/completions',temperature:0.3,max_tokens:1024,timeout:30,enabled:true});renderModels()}function removeModel(i){modelState.models.splice(i,1);renderModels()}
async function saveModels(){const fallbackOrder=[...document.querySelectorAll('[data-fallback-id]:checked')].map(x=>x.dataset.fallbackId);modelState.routing={general:$('route-general').value,ticket:$('route-ticket').value,vision:$('route-vision').value,fallback:$('route-fallback').value,fallback_order:fallbackOrder};try{const d=await api('/api/models',{method:'PUT',body:JSON.stringify(modelState)});toast(d.message||'多个 AI API 已保存');loadModels();loadHistory()}catch(e){toast(e.message,'error')}}
async function testModel(i){try{const d=await api('/api/models/test',{method:'POST',body:JSON.stringify(modelState.models[i])});toast(d.message)}catch(e){toast(e.message)}}
const ticketStatusLabels={open:'待处理',assigned:'已分配',in_progress:'处理中',resolved:'待用户确认',closed:'已关闭'};
const ticketPriorityLabels={urgent:'紧急',high:'高',medium:'中',low:'低'};
const ticketTypeLabels={incident:'故障事件',request:'服务请求',service_request:'服务请求'};
const ticketSlaLabels={normal:'正常',at_risk:'即将超时',breached:'已超时',met:'已达标',paused:'已暂停'};
function openTicketFromAnywhere(ticketId){const id=String(ticketId||'').trim();if(!id)return;openConsoleView('tickets','工单','tickets');showTicket(id)}
function ticketLinkMarkup(ticketId,fallback='—'){const id=String(ticketId||'').trim();if(!id)return esc(fallback);return`<button type="button" class="ticket-link" data-ticket-id="${encodeURIComponent(id)}" onclick="event.stopPropagation();openTicketFromAnywhere(decodeURIComponent(this.dataset.ticketId))">${esc(id)}</button>`}
function collectTicketParams(){const params=new URLSearchParams({page:String(ticketState.page),page_size:String(ticketState.pageSize),format:'page'}),value=(id)=>$(id)?.value.trim()||'';const add=(key,v)=>{if(v)params.append(key,v)};add('q',value('ticket-q'));const explicitStatus=value('ticket-status');if(explicitStatus)add('status',explicitStatus);else if(ticketState.quick==='pending')['open','assigned','in_progress'].forEach(x=>add('status',x));else if(ticketState.quick==='done')['resolved','closed'].forEach(x=>add('status',x));else if(ticketState.quick==='awaiting_confirmation')add('status','resolved');add('priority',value('ticket-filter-priority'));add('category',value('ticket-category'));add('assignee',value('ticket-assignee'));add('assignment_group',value('ticket-assignment-group'));add('service_code',value('ticket-service'));add('request_type',value('ticket-request-type'));add('sla_status',value('ticket-sla'));add('created_from',value('ticket-created-from'));add('created_to',value('ticket-created-to'));if(ticketState.quick==='unassigned')params.set('unassigned','1');if(ticketState.quick==='at_risk')params.set('sla_status','at_risk');if(ticketState.quick==='breached')params.set('sla_status','breached');if(ticketState.quick==='reopened')params.set('confirmation','reopened');return params}
function ticketSlaMarkup(t){const status=t.sla_status||'',label=ticketSlaLabels[status]||status||'未设置',due=t.resolution_due_at||t.response_due_at||'';return `<span class="badge sla-${esc(status||'unset')}">${esc(label)}</span>${due?`<small class="cell-note">${esc(due)}</small>`:''}`}
function renderTicketRows(){const rows=ticketState.items;$('ticket-list').innerHTML=rows.map(t=>`<tr class="${ticketState.currentId===t.ticket_id?'row-active':''}" onclick="showTicket('${esc(t.ticket_id)}')"><td onclick="event.stopPropagation()"><input type="checkbox" aria-label="选择 ${esc(t.ticket_id)}" ${ticketState.selected.has(t.ticket_id)?'checked':''} onchange="toggleTicketSelection('${esc(t.ticket_id)}',this.checked)"></td><td><b>${esc(t.ticket_id)}</b></td><td>${esc(t.title)}</td><td>${esc(t.service_name||'未指定')}<small class="cell-note">${esc(ticketTypeLabels[t.request_type]||t.request_type||'故障事件')}</small></td><td><span class="badge">${esc(ticketStatusLabels[t.status]||t.status)}</span></td><td class="priority-${esc(t.priority)}">${esc(ticketPriorityLabels[t.priority]||t.priority)}</td><td>${ticketSlaMarkup(t)}</td><td>${esc(t.assignee_nick||'未分配')}<small class="cell-note">${esc(t.assignment_group||'未设置处理组')}</small></td><td>${esc(t.created_at)}</td></tr>`).join('')||'<tr><td colspan="9" class="table-empty">没有符合条件的工单</td></tr>';const all=rows.length&&rows.every(t=>ticketState.selected.has(t.ticket_id));$('ticket-select-all').checked=!!all;$('ticket-select-all').indeterminate=!all&&rows.some(t=>ticketState.selected.has(t.ticket_id));refreshTicketSelection()}
async function loadTickets(filter,options={}){if(filter){ticketState.quick=filter;currentTicketFilter=filter}if(ticketState.loading)return;const silent=options.silent===true;ticketState.loading=true;if(!silent)$('ticket-list').innerHTML='<tr><td colspan="9" class="table-empty">正在读取工单…</td></tr>';try{const d=await api('/api/tickets?'+collectTicketParams().toString(),{cache:'no-store'}),page=Array.isArray(d)?{items:d,total:d.length,page:1,page_size:d.length||ticketState.pageSize}:d;ticketState.items=page.items||[];ticketState.total=Number(page.total||0);ticketState.page=Number(page.page||ticketState.page);ticketState.pageSize=Number(page.page_size||ticketState.pageSize);renderTicketRows();const pages=Math.max(1,Math.ceil(ticketState.total/ticketState.pageSize));$('ticket-result-summary').textContent=`共 ${ticketState.total} 条`;$('ticket-page-label').textContent=`第 ${ticketState.page} / ${pages} 页`;$('ticket-prev').disabled=ticketState.page<=1;$('ticket-next').disabled=ticketState.page>=pages;if($('ticket-last-updated'))$('ticket-last-updated').textContent=`最后更新：${new Date().toLocaleTimeString('zh-CN',{hour12:false})}` }catch(e){if(!silent){ticketState.items=[];$('ticket-list').innerHTML=`<tr><td colspan="9" class="table-empty error-text">${esc(e.message)}</td></tr>`;toast(e.message,'error')}}finally{ticketState.loading=false}}
function setTicketQuickView(name,button){ticketState.quick=name;currentTicketFilter=name;ticketState.page=1;ticketState.selected.clear();document.querySelectorAll('[data-ticket-quick]').forEach(x=>x.classList.toggle('active',x===button||x.dataset.ticketQuick===name));loadTickets()}
function applyTicketFilters(){ticketState.page=1;ticketState.selected.clear();loadTickets()}
function resetTicketFilters(){['ticket-q','ticket-status','ticket-filter-priority','ticket-category','ticket-assignee','ticket-assignment-group','ticket-service','ticket-request-type','ticket-sla','ticket-created-from','ticket-created-to'].forEach(id=>{if($(id))$(id).value='' });setTicketQuickView('all',document.querySelector('[data-ticket-quick="all"]'))}
function searchTickets(){applyTicketFilters()}function clearTicketSearch(){resetTicketFilters()}
function exportTickets(){const params=collectTicketParams();params.delete('page');params.delete('page_size');params.delete('format');window.location.href='/api/tickets/export?'+params.toString()}
function changeTicketPage(delta){const pages=Math.max(1,Math.ceil(ticketState.total/ticketState.pageSize)),next=Math.min(pages,Math.max(1,ticketState.page+delta));if(next!==ticketState.page){ticketState.page=next;loadTickets()}}
function changeTicketPageSize(value){ticketState.pageSize=Number(value)||50;ticketState.page=1;loadTickets()}
function toggleTicketSelection(id,checked){if(checked)ticketState.selected.add(id);else ticketState.selected.delete(id);refreshTicketSelection()}
function toggleTicketPage(checked){ticketState.items.forEach(t=>checked?ticketState.selected.add(t.ticket_id):ticketState.selected.delete(t.ticket_id));renderTicketRows()}
function refreshTicketSelection(){$('ticket-selected-count').textContent=ticketState.selected.size;$('ticket-batch-submit').disabled=!ticketState.selected.size||!$('ticket-batch-action').value}
function updateBatchControls(){const action=$('ticket-batch-action').value;$('ticket-batch-assignee').hidden=action!=='assign';$('ticket-batch-priority').hidden=action!=='priority';$('ticket-batch-detail').hidden=!['progress','close','invalid'].includes(action);refreshTicketSelection()}
async function runTicketBatch(){const ids=[...ticketState.selected],action=$('ticket-batch-action').value;if(!ids.length)return toast('请先选择工单','error');if(!action)return toast('请选择批量操作','error');if(['close','invalid'].includes(action)&&!confirm(`确定对 ${ids.length} 条工单执行此操作？`))return;const assignee=$('ticket-batch-assignee'),payload={ticket_ids:ids,action,assignee_id:assignee.value,assignee_nick:assignee.options[assignee.selectedIndex]?.text||'',priority:$('ticket-batch-priority').value,detail:$('ticket-batch-detail').value.trim()};const button=$('ticket-batch-submit'),old=button.textContent;button.disabled=true;button.textContent='处理中…';try{const d=await api('/api/tickets/batch',{method:'POST',body:JSON.stringify(payload)}),failures=(d.results||[]).filter(x=>!x.ok);(d.results||[]).filter(x=>x.ok).forEach(x=>ticketState.selected.delete(x.ticket_id));toast(`批量处理完成：成功 ${d.succeeded}，失败 ${d.failed}${failures.length?'；'+failures.slice(0,3).map(x=>`${x.ticket_id} ${x.message}`).join('；'):''}`,failures.length?'error':'info',failures.length?9000:3500);await loadTickets()}catch(e){toast(e.message,'error')}finally{button.textContent=old;updateBatchControls()}}
async function importTickets(file){if(!file)return;const body=new FormData();body.append('file',file);try{const response=await fetch('/api/tickets/import',{method:'POST',body}),text=await response.text();let d;try{d=JSON.parse(text)}catch(_){throw new Error(`导入服务返回无效响应（HTTP ${response.status}）`)}if(!response.ok)throw new Error(d.message||'导入失败');const errors=d.errors||[];toast(`导入 ${d.imported} 条，跳过 ${d.skipped} 条，错误 ${errors.length} 条${errors.length?'；'+errors.slice(0,3).join('；'):''}`,errors.length?'error':'info',errors.length?9000:3500);ticketState.page=1;await loadTickets()}catch(e){toast(e.message,'error')}finally{$('ticket-import-file').value=''}}
async function loadTicketHistory(){try{const id=ticketState.currentId||'',rows=await api('/api/tickets/history'+(id?`?ticket_id=${encodeURIComponent(id)}`:''));$('ticket-history-panel').hidden=false;$('ticket-history-list').innerHTML=rows.map(x=>`<tr><td>${ticketLinkMarkup(x.ticket_id)}</td><td>${esc(x.action)}</td><td>${esc(x.operator_nick||x.operator_id)}</td><td>${esc(x.detail||'')}</td><td>${esc(x.created_at)}</td></tr>`).join('')||'<tr><td colspan="5">暂无历史记录</td></tr>'}catch(e){toast(e.message,'error')}}
function ticketActionButtons(t){const id=esc(t.ticket_id),allowed={open:['assign','progress','resolve','close','invalid'],assigned:['progress','resolve','close','invalid'],in_progress:['assign','resolve','close','invalid'],resolved:['reopen'],closed:[]}[t.status]||[],base=['open','assigned','in_progress'].includes(t.status)?['priority','comment']:t.status==='resolved'?['comment']:[],labels={assign:'分派',progress:'开始处理',resolve:'标记解决',reopen:'重新打开',close:'关闭并等待确认',invalid:'标记无效'},style={resolve:'primary',close:'primary',invalid:'danger'};const buttons=[...base,...allowed].map(action=>`<button class="${style[action]||'secondary'}" onclick="ticketAction('${id}','${action}')">${labels[action]||({'priority':'改优先级','comment':'添加记录'}[action])}</button>`);if(t.status==='resolved')buttons.unshift(`<button class="primary" onclick="confirmTicketResolution('${id}')">代用户确认恢复</button>`);return buttons.join('')||'<span class="muted">工单已完结，仅可查看记录</span>'}
async function showTicket(id){if(!$('tickets').classList.contains('active'))activateView('tickets','工单工作台');ticketState.currentId=id;renderTicketRows();$('ticket-detail').innerHTML='<p class="empty">正在读取详情…</p>';try{const d=await api('/api/tickets/'+encodeURIComponent(id)),t=d.ticket,people=(settings.people||[]).map(p=>`<option value="${esc(p.staff_id||p.name)}" ${(p.staff_id||p.name)===t.assignee_id?'selected':''}>${esc(p.name)}</option>`).join(''),feedback=d.feedback||[];$('ticket-detail').innerHTML=`<div class="item-head"><div><h3>${esc(t.title)}</h3><p>${esc(t.ticket_id)} ${t.is_invalid?'<span class="badge">无效工单</span>':''}</p></div>${ticketSlaMarkup(t)}</div>${ticketIssueContextMarkup(d.issue)}<div class="meta"><span>状态：${esc(ticketStatusLabels[t.status]||t.status)}</span><span>优先级：${esc(ticketPriorityLabels[t.priority]||t.priority)}</span><span>创建人：${esc(t.creator_nick)}</span><span>负责人：${esc(t.assignee_nick||'未分配')}</span><span>服务：${esc(t.service_name||'未指定')}</span><span>类型：${esc(ticketTypeLabels[t.request_type]||t.request_type||'故障事件')}</span><span>处理组：${esc(t.assignment_group||'未设置')}</span><span>响应期限：${esc(t.response_due_at||'—')}</span><span>解决期限：${esc(t.resolution_due_at||'—')}</span><span>用户确认：${esc(t.user_confirmation||'待确认')}</span><span>用户评分：${t.feedback_score?esc(t.feedback_score)+' / 5':'—'}</span></div><div class="body">${esc(t.description||t.title)}</div><div class="inline-fields"><label>负责人<select id="ticket-person"><option value="">选择人员</option>${people}</select></label><label>优先级<select id="ticket-priority"><option value="urgent" ${t.priority==='urgent'?'selected':''}>紧急</option><option value="high" ${t.priority==='high'?'selected':''}>高</option><option value="medium" ${t.priority==='medium'?'selected':''}>中</option><option value="low" ${t.priority==='low'?'selected':''}>低</option></select></label></div><div class="inline-fields"><label>记录可见性<select id="ticket-note-visibility"><option value="internal">内部备注（不通知用户）</option><option value="public">公开回复（通知用户）</option></select></label><label>本次处理记录<textarea id="ticket-detail-note" placeholder="填写排查、沟通或关闭原因"></textarea></label></div><label>解决方案<textarea id="ticket-resolution">${esc(t.resolution||'')}</textarea></label><div class="item-actions ticket-actions">${ticketActionButtons(t)}</div><h4>处理时间线</h4><div class="timeline">${(d.logs||[]).map(l=>`<p><b>${esc(l.action)}</b>${l.visibility?` <span class="badge">${l.visibility==='internal'?'内部':'公开'}</span>`:''} · ${esc(l.operator_nick||l.operator_id||'系统')} · ${esc(l.created_at)}<br>${esc(l.detail||'')}</p>`).join('')||'<p>暂无处理记录</p>'}</div><h4>用户反馈</h4><div class="timeline">${feedback.map(f=>`<p><b>${f.score?esc(f.score)+' / 5':(f.confirmed===false?'未解决':'已确认')}</b> · ${esc(f.created_at||f.updated_at||'')}<br>${esc(f.comment||'未填写评价')}</p>`).join('')||'<p>暂无用户反馈</p>'}</div>`}catch(e){$('ticket-detail').innerHTML=`<p class="empty error-text">${esc(e.message)}</p>`;toast(e.message,'error')}}
async function ticketAction(id,action){const person=$('ticket-person'),selected=person?.options[person.selectedIndex],payload={action,resolution:$('ticket-resolution')?.value.trim()||'',detail:$('ticket-detail-note')?.value.trim()||'',visibility:$('ticket-note-visibility')?.value||'internal',priority:$('ticket-priority')?.value||'medium',assignee_id:person?.value||'',assignee_nick:selected?.text||''};if(action==='comment'&&!payload.detail)return toast('请先填写处理记录','error');if(['resolve','close'].includes(action)&&!payload.resolution)return toast('关闭或解决前必须填写解决方案','error');if(action==='invalid'&&!payload.detail)return toast('标记无效前必须填写原因','error');if(action==='assign'&&!payload.assignee_id)return toast('请先选择负责人','error');if(['close','invalid'].includes(action)&&!confirm(action==='invalid'?'确定将此工单标记为无效？':'提交解决方案并等待用户确认？'))return;const buttons=[...document.querySelectorAll('#ticket-detail button')];buttons.forEach(x=>x.disabled=true);try{await api('/api/tickets/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify(payload)});toast(action==='close'?'已进入待用户确认状态':action==='comment'&&payload.visibility==='internal'?'内部备注已保存，不会通知提交人':'工单已更新');await Promise.all([showTicket(id),loadTickets()])}catch(e){toast(e.message,'error')}finally{buttons.forEach(x=>x.disabled=false)}}
async function confirmTicketResolution(id){const raw=prompt('用户评分（1-5，可留空）','5');if(raw===null)return;const score=raw.trim()===''?null:Number(raw);if(score!==null&&(!Number.isInteger(score)||score<1||score>5))return toast('评分必须是 1 到 5 的整数','error');const comment=prompt('用户评价（可留空）','')??'';try{await api(`/api/tickets/${encodeURIComponent(id)}/confirm`,{method:'POST',body:JSON.stringify({confirmed:true,score,comment})});toast('已记录用户确认，解决方案进入知识候选');await Promise.all([showTicket(id),loadTickets()])}catch(e){toast(e.message,'error')}}
const issueStatusLabels={open:'Open',ticketed:'已转工单',closed:'Closed'};
function ticketIssueContextMarkup(issue){if(!issue)return'';const steps=Array.isArray(issue.steps_json)?issue.steps_json:[],aiStatus=steps.length?'有处理步骤记录（现有数据未区分 AI 与人工）':'未记录，无法确认';return`<div class="form-panel"><div class="panel-head"><div><p>RELATED ISSUE</p><h3>关联 Issue · ${esc(issue.issue_id)}</h3></div><button class="ghost" onclick="openTicketIssue('${esc(issue.issue_id)}')">查看 Issue</button></div><div class="meta"><span>创建时间：${esc(issue.created_at||'—')}</span><span>用户：${esc(issue.user_id||'—')}</span><span>AI 是否处理过：${esc(aiStatus)}</span><span>当前状态：${esc(issueStatusLabels[issue.status]||issue.status)}</span></div><h4>原始问题</h4><div class="body">${esc(issue.original_question||'—')}</div><h4>已有步骤</h4>${issueStepsMarkup(steps)}<h4>最终结果</h4><div class="body">${esc(issue.final_result||'尚未记录')}</div></div>`}
async function loadIssues(filter=currentIssueFilter){currentIssueFilter=filter||'all';document.querySelectorAll('[data-issue-filter]').forEach(node=>node.classList.toggle('active',node.dataset.issueFilter===currentIssueFilter));const list=$('issue-list');if(list)list.innerHTML='<tr><td colspan="7">正在读取 Issue…</td></tr>';try{const d=await api(`/api/issues?filter=${encodeURIComponent(currentIssueFilter)}`,{cache:'no-store'}),items=d.items||[];if(!d.enabled){list.innerHTML=`<tr><td colspan="7">${esc(d.message||'Issue 记录当前未启用')}</td></tr>`;return}list.innerHTML=items.map(issue=>`<tr onclick="showIssue('${esc(issue.issue_id)}')"><td>${esc(issue.issue_id)}</td><td>${esc(issue.created_at)}</td><td><span class="badge">${esc(issueStatusLabels[issue.status]||issue.status)}</span></td><td>${esc(issue.original_question)}</td><td>${esc(issue.user_id||'—')}</td><td>${ticketLinkMarkup(issue.ticket_id)}</td><td>${issue.status==='closed'?'是':'否'}</td></tr>`).join('')||'<tr><td colspan="7">当前筛选下没有 Issue</td></tr>'}catch(e){list.innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`;toast(e.message,'error')}}
function issueStepsMarkup(steps){if(!Array.isArray(steps)||!steps.length)return'<p class="empty">当前没有步骤记录</p>';return steps.map((step,index)=>`<div class="timeline"><p><b>步骤 ${index+1}</b></p><pre>${esc(typeof step==='string'?step:JSON.stringify(step,null,2))}</pre></div>`).join('')}
async function showIssue(id){const detail=$('issue-detail');detail.innerHTML='<p class="empty">正在读取 Issue 详情…</p>';try{const d=await api(`/api/issues/${encodeURIComponent(id)}`,{cache:'no-store'}),issue=d.issue;detail.innerHTML=`<div class="item-head"><div><h3>${esc(issue.issue_id)}</h3><p><span class="badge">${esc(issueStatusLabels[issue.status]||issue.status)}</span></p></div></div><h4>原始问题</h4><div class="body">${esc(issue.original_question||'—')}</div><div class="meta"><span>创建时间：${esc(issue.created_at||'—')}</span><span>更新时间：${esc(issue.updated_at||'—')}</span><span>用户：${esc(issue.user_id||'—')}</span><span>会话：${esc(issue.conversation_id||'—')}</span><span>当前状态：${esc(issueStatusLabels[issue.status]||issue.status)}</span><span>关联工单：${esc(issue.ticket_id||'未关联')}</span></div>${issue.ticket_id?`<div class="item-actions"><button class="primary" onclick="openIssueTicket('${esc(issue.ticket_id)}')">查看工单</button></div>`:''}<h4>最终结果</h4><div class="body">${esc(issue.final_result||'尚未记录')}</div><h4>已有步骤信息</h4>${issueStepsMarkup(issue.steps_json)}`}catch(e){detail.innerHTML=`<p class="empty error-text">${esc(e.message)}</p>`;toast(e.message,'error')}}
function openIssueTicket(ticketId){openConsoleView('tickets','工单','issues');showTicket(ticketId)}
function openTicketIssue(issueId){openConsoleView('issues','Issue 记录','tickets');showIssue(issueId)}
function syncTicketFilterOptions(){const people=settings.people||[],catalog=settings.service_catalog||[],personOptions=people.map(p=>`<option value="${esc(p.staff_id||p.name)}">${esc(p.name)}</option>`).join(''),serviceOptions=catalog.map(s=>`<option value="${esc(s.code||s.id)}">${esc(s.name)}</option>`).join('');[['ticket-assignee','全部负责人'],['ticket-batch-assignee','选择负责人']].forEach(([id,label])=>{const el=$(id);if(!el)return;const old=el.value;el.innerHTML=`<option value="">${label}</option>${personOptions}`;el.value=old});const filter=$('ticket-service'),create=$('new-ticket-service');if(filter){const old=filter.value;filter.innerHTML='<option value="">全部服务项</option>'+serviceOptions;filter.value=old}if(create){create.innerHTML='<option value="">未指定服务</option>'+catalog.filter(s=>s.enabled!==false).map(s=>`<option value="${esc(s.code||s.id)}">${esc(s.name)}</option>`).join('')}const categories=[...new Set(['设备问题','业务系统问题','CRM问题','软件问题','其他',...catalog.map(s=>s.category).filter(Boolean)])];if($('ticket-category-options'))$('ticket-category-options').innerHTML=categories.map(x=>`<option value="${esc(x)}"></option>`).join('');updateBatchControls()}
function openCreateTicket(){syncTicketFilterOptions();const dialog=$('ticket-create-dialog');if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','')}
function closeCreateTicket(){const dialog=$('ticket-create-dialog');if(dialog.close)dialog.close();else dialog.removeAttribute('open')}
async function createTicket(){const button=$('new-ticket-submit'),old=button.textContent,payload={creator_nick:$('new-ticket-creator').value.trim(),creator_staff_id:$('new-ticket-staff').value.trim(),creator_id:$('new-ticket-staff').value.trim(),service_code:$('new-ticket-service').value,title:$('new-ticket-title').value.trim(),description:$('new-ticket-description').value.trim()};button.disabled=true;button.textContent='创建中…';try{const d=await api('/api/tickets',{method:'POST',body:JSON.stringify(payload)});closeCreateTicket();['new-ticket-creator','new-ticket-staff','new-ticket-title','new-ticket-description'].forEach(id=>$(id).value='');$('new-ticket-service').value='';ticketState.page=1;ticketState.quick='all';await loadTickets();toast(`工单 ${d.ticket.ticket_id} 已创建`);showTicket(d.ticket.ticket_id)}catch(e){toast(e.message,'error')}finally{button.disabled=false;button.textContent=old}}
function renderServiceCatalog(){const list=settings.service_catalog||[];$('catalog-enabled-count').textContent=list.filter(x=>x.enabled!==false).length;$('service-catalog-list').innerHTML=list.length?list.map((s,i)=>`<article class="item-card catalog-card"><div class="item-head"><div><h3>${esc(s.name||'未命名服务')}</h3><p>${esc(s.code||s.id||'未设置编码')} · ${s.enabled!==false?'已启用':'已停用'}</p></div><button class="danger" onclick="removeServiceItem(${i})">删除</button></div><div class="form-grid top-gap"><label>服务编码<input value="${esc(s.code||s.id||'')}" maxlength="64" onchange="settings.service_catalog[${i}].code=this.value.trim()"></label><label>服务名称<input value="${esc(s.name||'')}" maxlength="80" onchange="settings.service_catalog[${i}].name=this.value"></label><label>类型<select onchange="settings.service_catalog[${i}].request_type=this.value"><option value="incident" ${(s.request_type||'incident')==='incident'?'selected':''}>故障事件</option><option value="service_request" ${['request','service_request'].includes(s.request_type)?'selected':''}>服务请求</option></select></label><label>分类<input value="${esc(s.category||'其他')}" onchange="settings.service_catalog[${i}].category=this.value"></label><label>默认优先级<select onchange="settings.service_catalog[${i}].priority=this.value"><option value="urgent" ${(s.priority||s.default_priority)==='urgent'?'selected':''}>紧急</option><option value="high" ${(s.priority||s.default_priority)==='high'?'selected':''}>高</option><option value="medium" ${(s.priority||s.default_priority||'medium')==='medium'?'selected':''}>中</option><option value="low" ${(s.priority||s.default_priority)==='low'?'selected':''}>低</option></select></label><label>处理组<input value="${esc(s.assignment_group||'')}" onchange="settings.service_catalog[${i}].assignment_group=this.value"></label><label>负责人 ID（钉钉 staffId）<input value="${esc(s.owner_id||'')}" maxlength="128" placeholder="推荐填写稳定 ID" onchange="settings.service_catalog[${i}].owner_id=this.value.trim()"></label><label>负责人名称<input value="${esc(s.owner_name||'')}" maxlength="80" onchange="settings.service_catalog[${i}].owner_name=this.value.trim()"></label><label>首次响应目标（小时）<input type="number" min="0.1" max="8760" step="0.1" value="${esc(s.response_hours??4)}" onchange="settings.service_catalog[${i}].response_hours=Number(this.value)"></label><label>解决目标（小时）<input type="number" min="0.1" max="8760" step="0.1" value="${esc(s.resolution_hours??24)}" onchange="settings.service_catalog[${i}].resolution_hours=Number(this.value)"></label><label class="switch-row compact">启用<input type="checkbox" ${s.enabled!==false?'checked':''} onchange="settings.service_catalog[${i}].enabled=this.checked;renderServiceCatalog()"><span class="switch"></span></label><label class="switch-row compact">需要审批<input type="checkbox" ${s.approval_required?'checked':''} onchange="settings.service_catalog[${i}].approval_required=this.checked"><span class="switch"></span></label></div><label>关键词<input value="${esc(Array.isArray(s.keywords)?s.keywords.join('，'):(s.keywords||''))}" onchange="settings.service_catalog[${i}].keywords=this.value"></label><label>服务说明<textarea onchange="settings.service_catalog[${i}].description=this.value">${esc(s.description||'')}</textarea></label><label>提交指引<textarea onchange="settings.service_catalog[${i}].instructions=this.value">${esc(s.instructions||'')}</textarea></label></article>`).join(''):'<div class="form-panel">尚未配置服务项。先添加常见故障或服务请求，工单即可自动带出优先级和 SLA。</div>';syncTicketFilterOptions()}
function addServiceItem(){settings.service_catalog=settings.service_catalog||[];settings.service_catalog.push({code:`SVC-${Date.now().toString(36).toUpperCase()}`,name:'新服务项',enabled:true,request_type:'incident',category:'其他',priority:'medium',assignment_group:'',owner_id:'',owner_name:'',response_hours:4,resolution_hours:24,keywords:[],approval_required:false,instructions:''});renderServiceCatalog()}
function removeServiceItem(index){if(!confirm('确定删除此服务项？保存后生效。'))return;settings.service_catalog.splice(index,1);renderServiceCatalog()}
async function saveServiceCatalog(){try{const d=await saveSection('service_catalog');settings.service_catalog=d.data||settings.service_catalog;renderServiceCatalog();syncTicketFilterOptions();loadHistory()}catch(_){}}
async function loadHistory(){const rows=await api('/api/config-history');$('history-list').innerHTML=rows.map(h=>`<tr><td>${esc(h.created_at)}</td><td>${esc(h.section)}</td><td>${esc(h.description)}</td><td><button class="danger" onclick="rollbackConfig('${esc(h.version)}')">回滚</button></td></tr>`).join('')||'<tr><td colspan="4">暂无配置历史</td></tr>'}
async function rollbackConfig(v){if(!confirm('确定回滚到这个版本？当前配置会先自动备份。'))return;try{const d=await api('/api/config-history/'+v+'/rollback',{method:'POST'});toast(d.message);setTimeout(()=>location.reload(),1000)}catch(e){toast(e.message)}}
const knowledgeStatusLabels={draft:'待审核',approved:'已审核',published:'已发布',rejected:'已驳回'};
let knowledgeAccessState=[];
const csvValues=value=>String(value||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);
async function loadKnowledgeAccess(){try{const d=await api('/api/knowledge/access',{cache:'no-store'});knowledgeAccessState=d.items||[];$('knowledge-access-list').innerHTML=knowledgeAccessState.map((k,i)=>`<article class="item-card"><div class="item-head"><div><h3>${esc(k.name)}</h3><p>${esc(k.id==='local-published'?'本地发布知识':'IMA 知识库')}</p></div><label>访问范围<select onchange="knowledgeAccessState[${i}].access_scope=this.value;renderKnowledgeAccess()"><option value="public" ${k.access_scope==='public'?'selected':''}>全员可用</option><option value="restricted" ${k.access_scope==='restricted'?'selected':''}>指定人员/部门/角色</option><option value="admin" ${k.access_scope==='admin'?'selected':''}>仅管理员</option></select></label></div>${k.access_scope==='restricted'?`<div class="inline-fields"><label>Staff ID<input value="${esc((k.allowed_staff_ids||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_staff_ids=csvValues(this.value)" placeholder="staff001, staff002"></label><label>部门<input value="${esc((k.allowed_departments||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_departments=csvValues(this.value)" placeholder="财务部, 运维部"></label><label>角色<input value="${esc((k.allowed_roles||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_roles=csvValues(this.value)" placeholder="运维人员"></label></div>`:''}</article>`).join('')||'<div class="empty">尚未配置知识库</div>'}catch(e){toast(`读取知识权限失败：${e.message}`,'error')}}
function renderKnowledgeAccess(){const snapshot=knowledgeAccessState;const list=$('knowledge-access-list');if(!list)return;list.innerHTML=snapshot.map((k,i)=>`<article class="item-card"><div class="item-head"><div><h3>${esc(k.name)}</h3><p>${esc(k.id==='local-published'?'本地发布知识':'IMA 知识库')}</p></div><label>访问范围<select onchange="knowledgeAccessState[${i}].access_scope=this.value;renderKnowledgeAccess()"><option value="public" ${k.access_scope==='public'?'selected':''}>全员可用</option><option value="restricted" ${k.access_scope==='restricted'?'selected':''}>指定人员/部门/角色</option><option value="admin" ${k.access_scope==='admin'?'selected':''}>仅管理员</option></select></label></div>${k.access_scope==='restricted'?`<div class="inline-fields"><label>Staff ID<input value="${esc((k.allowed_staff_ids||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_staff_ids=csvValues(this.value)"></label><label>部门<input value="${esc((k.allowed_departments||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_departments=csvValues(this.value)"></label><label>角色<input value="${esc((k.allowed_roles||[]).join(', '))}" onchange="knowledgeAccessState[${i}].allowed_roles=csvValues(this.value)"></label></div>`:''}</article>`).join('')}
async function saveKnowledgeAccess(){try{const d=await api('/api/knowledge/access',{method:'PUT',body:JSON.stringify({items:knowledgeAccessState})});toast(d.message);loadHistory()}catch(e){toast(e.message,'error')}}
async function loadKnowledge(status=currentKnowledgeFilter,options={}){currentKnowledgeFilter=status;const silent=options.silent===true;try{const [items,unresolved,metrics]=await Promise.all([api('/api/knowledge/candidates'+(status?'?status='+status:''),{cache:'no-store'}),api('/api/knowledge/unresolved',{cache:'no-store'}),api('/api/knowledge/metrics',{cache:'no-store'})]);$('knowledge-total').textContent=items.length;$('knowledge-unresolved').textContent=unresolved.length;$('knowledge-low').textContent=metrics.filter(m=>m.fail_count>m.success_count).length;$('knowledge-list').innerHTML=items.map(k=>`<tr onclick="showKnowledge('${esc(k.id)}')"><td>${esc(k.id)}</td><td>${esc(k.title)}</td><td><span class="badge">${esc(knowledgeStatusLabels[k.status]||k.status)}</span></td><td>${esc(k.quality_score)}</td><td>${esc(k.duplicate_of||'—')}</td></tr>`).join('')||'<tr><td colspan="5">暂无知识候选</td></tr>';$('knowledge-unresolved-list').innerHTML=unresolved.map(x=>`<tr><td>${esc(x.question)}</td><td>${ticketLinkMarkup(x.ticket_id)}</td><td>${esc(x.updated_at)}</td><td><button class="secondary" onclick="createKnowledgeFromUnresolved(${Number(x.id)})">转为草稿</button></td></tr>`).join('')||'<tr><td colspan="4">暂无未解决问题</td></tr>';$('knowledge-metrics').innerHTML=metrics.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.source_kb)}</td><td>${m.use_count}</td><td>${m.success_count}</td><td>${m.fail_count}</td><td>${m.success_rate}%</td></tr>`).join('')||'<tr><td colspan="6">暂无知识使用数据</td></tr>'}catch(e){if(!silent)toast(e.message,'error')}}
function knowledgeActionButtons(k,id){const safe=esc(id),buttons=[`<button class="secondary" onclick="saveKnowledge('${safe}')">保存</button>`];if(['draft','rejected'].includes(k.status))buttons.push(`<button class="primary" onclick="knowledgeAction('${safe}','approve')">审核通过</button>`);if(['draft','approved'].includes(k.status))buttons.push(`<button class="danger" onclick="knowledgeAction('${safe}','reject')">驳回</button>`);if(k.status==='approved')buttons.push(`<button class="primary" onclick="knowledgeAction('${safe}','publish')">发布到本地并导出</button>`);if(k.status==='published')buttons.push(`<button class="primary" onclick="viewKnowledgeExport('${safe}')">查看导出文件</button>`);return buttons.join('')}
async function openKnowledgeExportDirectory(){try{const d=await api('/api/knowledge/exports/open-directory',{method:'POST',body:'{}'});toast(`${d.message}：${d.path||''}`)}catch(e){const message=e.status===404?'当前后台仍是旧版本，请重启 OpsPilot 服务后再打开导出目录':`打开知识导出目录失败：${e.message}`;toast(message,'error')}}
async function loadKnowledgeExportDirectory(){try{const d=await api('/api/knowledge/export-directory');const input=$('knowledge-export-directory'),result=$('knowledge-export-directory-result');if(input)input.value=d.configured_path||'';if(result)result.textContent=`当前目录：${d.resolved_path}${d.using_default?'（默认）':''}`}catch(e){const result=$('knowledge-export-directory-result');if(result)result.textContent=`读取失败：${e.message}`}}
function knowledgeExportDirectoryPayload(){return{path:($('knowledge-export-directory')?.value||'').trim()}}
async function selectKnowledgeExportDirectory(){try{toast('请选择知识导出目录…');const d=await api('/api/knowledge/export-directory/select',{method:'POST',body:'{}'});if(d.cancelled){toast(d.message);return}$('knowledge-export-directory').value=d.path||'';$('knowledge-export-directory-result').textContent=`已选择：${d.resolved_path}`;toast('目录已选择，请点击“保存配置”使其生效')}catch(e){toast(`选择目录失败：${e.message}`,'error')}}
async function testKnowledgeExportDirectory(){try{const d=await api('/api/knowledge/export-directory/test',{method:'POST',body:JSON.stringify(knowledgeExportDirectoryPayload())});$('knowledge-export-directory-result').textContent=`${d.message}：${d.resolved_path}`;toast(d.message)}catch(e){$('knowledge-export-directory-result').textContent=`测试失败：${e.message}`;toast(e.message,'error')}}
async function saveKnowledgeExportDirectory(){try{const d=await api('/api/knowledge/export-directory',{method:'PUT',body:JSON.stringify(knowledgeExportDirectoryPayload())});$('knowledge-export-directory').value=d.configured_path||'';$('knowledge-export-directory-result').textContent=`当前目录：${d.resolved_path}${d.using_default?'（默认）':''}`;toast(d.message)}catch(e){$('knowledge-export-directory-result').textContent=`保存失败：${e.message}`;toast(e.message,'error')}}
async function openConfiguredKnowledgeExportDirectory(){try{const d=await api('/api/knowledge/exports/open-directory',{method:'POST',body:JSON.stringify(knowledgeExportDirectoryPayload())});$('knowledge-export-directory-result').textContent=`已打开：${d.path}`;toast(d.message)}catch(e){$('knowledge-export-directory-result').textContent=`打开失败：${e.message}`;toast(`打开目录失败：${e.message}`,'error')}}
async function viewKnowledgeExport(id){const url=`/api/knowledge/candidates/${encodeURIComponent(id)}/export`;try{const response=await fetch(url,{cache:'no-store'});if(!response.ok){let message='';try{const data=await response.json();message=data.message||''}catch(_){}const error=new Error(message||`请求失败，HTTP ${response.status}`);error.status=response.status;throw error}const blob=await response.blob(),blobUrl=URL.createObjectURL(blob),link=document.createElement('a');link.href=blobUrl;link.target='_blank';link.rel='noopener';link.click();setTimeout(()=>URL.revokeObjectURL(blobUrl),60000)}catch(e){const message=e.status===404?'导出文件接口不可用，或文件已不存在；请重启服务并重新发布该知识':`查看导出文件失败：${e.message}`;toast(message,'error')}}
async function showKnowledge(id){const d=await api('/api/knowledge/candidates/'+id),k=d.candidate;$('knowledge-detail').innerHTML=`<h3>${esc(k.title)}</h3><p>${esc(k.id)} · ${esc(knowledgeStatusLabels[k.status]||k.status)} · 质量分 ${esc(k.quality_score)}</p>${k.source_ticket_id?`<p>来源工单：${ticketLinkMarkup(k.source_ticket_id)}</p>`:''}${k.duplicate_of?`<p class="badge">可能与 ${esc(k.duplicate_of)} 重复</p>`:''}<label>标题<input id="kb-title" value="${esc(k.title)}"></label><label>适用范围<input id="kb-scope" value="${esc(k.scope||'')}"></label><label>问题现象<textarea id="kb-problem">${esc(k.problem)}</textarea></label><label>处理步骤<textarea id="kb-solution" rows="7">${esc(k.solution)}</textarea></label><label>验证方式<textarea id="kb-validation">${esc(k.validation||'')}</textarea></label><label>无效时<textarea id="kb-fallback">${esc(k.fallback||'')}</textarea></label><div class="item-actions">${knowledgeActionButtons(k,id)}</div><h4>版本历史</h4><div class="timeline">${d.versions.map(v=>`<p>V${v.version} · ${esc(v.action)} · ${esc(v.created_at)} <button class="ghost" onclick="rollbackKnowledge('${esc(id)}',${v.version})">恢复</button></p>`).join('')}</div>`}
async function saveKnowledge(id){const body={title:$('kb-title').value,scope:$('kb-scope').value,problem:$('kb-problem').value,solution:$('kb-solution').value,validation:$('kb-validation').value,fallback:$('kb-fallback').value};try{await api('/api/knowledge/candidates/'+id,{method:'PUT',body:JSON.stringify(body)});toast('知识草稿已保存');showKnowledge(id);loadKnowledge()}catch(e){toast(e.message)}}
async function knowledgeAction(id,action){try{const d=await api(`/api/knowledge/candidates/${id}/${action}`,{method:'POST'});toast(d.message||'知识状态已更新');showKnowledge(id);loadKnowledge()}catch(e){toast(e.message)}}
async function createKnowledgeFromUnresolved(id){try{const d=await api(`/api/knowledge/unresolved/${id}/candidate`,{method:'POST'});toast(d.message);await loadKnowledge();await showKnowledge(d.candidate_id)}catch(e){toast(e.message,'error')}}
async function rollbackKnowledge(id,version){if(!confirm('恢复此知识版本？'))return;try{await api(`/api/knowledge/candidates/${id}/rollback/${version}`,{method:'POST'});toast('知识版本已恢复');showKnowledge(id);loadKnowledge()}catch(e){toast(e.message)}}
async function loadTasks(status=''){try{const rows=await api('/api/tasks'+(status?'?status='+status:'')),labels={queued:'排队中',running:'处理中',cancellation_requested:'正在取消',succeeded:'已完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'};$('task-list').innerHTML=rows.map(t=>`<tr><td>${esc(t.task_id)}</td><td>${esc(t.task_type)}</td><td>${esc(t.title)}</td><td><span class="badge">${esc(labels[t.status]||t.status)}</span></td><td>${t.progress}%</td><td>${esc(t.created_at)}</td><td>${['queued','running','cancellation_requested'].includes(t.status)?`<button class="danger" onclick="cancelTask('${esc(t.task_id)}')">取消</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7">暂无后台任务</td></tr>'}catch(e){toast(e.message)}}
async function cancelTask(id){try{const d=await api(`/api/tasks/${id}/cancel`,{method:'POST'});toast(d.message);loadTasks()}catch(e){toast(e.message)}}
async function loadMonitor(){try{const [s,h,e]=await Promise.all([api('/api/monitor/summary'),api('/api/monitor/health'),api('/api/monitor/events?limit=50')]);$('mon-events').textContent=s.events_today;$('mon-errors').textContent=s.errors_today;$('mon-duration').textContent=s.avg_duration_ms+'ms';$('mon-running').textContent=s.tasks_running;$('mon-sent').textContent=s.notifications_sent;$('mon-failed').textContent=s.notifications_failed;$('monitor-health').innerHTML=h.map(x=>`<tr><td>${esc(x.component)}</td><td><span class="badge">${x.ok?'正常':'异常/未连接'}</span></td><td>${esc(x.detail)}</td></tr>`).join('');$('monitor-events').innerHTML=e.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.category)}</td><td>${esc(x.operation)}</td><td>${esc(x.status)}</td><td>${x.duration_ms}ms</td><td>${x.category==='ticket'?ticketLinkMarkup(x.detail):esc(x.detail||'—')}</td></tr>`).join('')||'<tr><td colspan="6">暂无运行事件</td></tr>';await loadNotifications()}catch(e){toast(e.message)}}
async function loadNotifications(status=''){try{const rows=await api('/api/monitor/notifications'+(status?'?status='+status:''));$('monitor-notifications').innerHTML=rows.map(x=>`<tr><td>${esc(x.updated_at)}</td><td>${ticketLinkMarkup(x.ticket_id)}</td><td>${esc(x.action)}</td><td>${esc(x.recipient)}</td><td><span class="badge">${esc(x.status)}</span></td><td>${x.attempts}</td><td>${esc(x.error_message||'—')}</td><td>${x.status==='failed'?`<button class="secondary" onclick="retryNotification(${x.id})">重试</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="8">暂无通知记录</td></tr>'}catch(e){toast(e.message)}}
async function retryNotification(id){try{const d=await api(`/api/monitor/notifications/${id}/retry`,{method:'POST'});toast(d.message);setTimeout(()=>loadNotifications(),1000)}catch(e){toast(e.message)}}
async function loadAITableSync(){try{const d=await api('/api/aitable-ticket-sync');$('aitable-enabled').checked=!!d.enabled;$('aitable-dws').value=d.dws_executable||'dws';$('aitable-base').value=d.base_id||'';$('aitable-table').value=d.table_id||'';$('aitable-interval').value=d.sync_interval_minutes||5;$('aitable-fields').value=JSON.stringify(d.field_mapping||{},null,2)}catch(e){toast(e.message)}}
function aitableSyncPayload(){let mapping={};const raw=$('aitable-fields').value.trim();if(raw)mapping=JSON.parse(raw);return{enabled:$('aitable-enabled').checked,dws_executable:$('aitable-dws').value.trim()||'dws',base_id:$('aitable-base').value.trim(),table_id:$('aitable-table').value.trim(),sync_interval_minutes:Number($('aitable-interval').value||5),field_mapping:mapping}}
async function saveAITableSync(){try{await api('/api/aitable-ticket-sync',{method:'PUT',body:JSON.stringify(aitableSyncPayload())});toast('智能表格同步配置已保存');loadHistory()}catch(e){toast('保存失败：'+e.message)}}
async function testAITableSync(){try{await saveAITableSync();const d=await api('/api/aitable-ticket-sync/test',{method:'POST'});$('aitable-result').textContent=d.message;toast(d.message)}catch(e){toast(e.message)}}
async function runAITableSync(){try{await saveAITableSync();$('aitable-result').textContent='正在同步…';const d=await api('/api/aitable-ticket-sync/sync',{method:'POST'}),r=d.result;$('aitable-result').textContent=`新增 ${r.created}，更新 ${r.updated}，失败 ${r.failed}`;toast('工单同步完成')}catch(e){$('aitable-result').textContent=e.message;toast(e.message)}}
async function loadNetwork(speed=false){try{$('net-detail').innerHTML='<p class="empty">正在检测，请稍候…</p>';const d=await api('/api/network/diagnose?speed='+(speed?'true':'false')),l=d.local,p=d.ping,n=d.dns;$('net-local').textContent=(l.local_ips||[]).join(', ')||'未获取';$('net-public').textContent=d.public.ip||'获取失败';$('net-latency').textContent=p.average_ms==null?'失败':p.average_ms+'ms';$('net-loss').textContent=p.loss_percent==null?'失败':p.loss_percent+'%';if(d.speed)$('net-speed').textContent=d.speed.ok?d.speed.download_mbps+'Mbps':'测速失败';$('net-interfaces').innerHTML=(l.interfaces||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc((x.ipv4||[]).join(', '))}</td><td>${esc(x.gateway||'—')}</td><td>${esc((x.dns||[]).join(', ')||'—')}</td></tr>`).join('')||'<tr><td colspan="4">没有检测到活动 IPv4 接口</td></tr>';$('net-detail').innerHTML=`<p><b>总体状态：</b>${d.ok?'网络基本正常':'存在连接异常'}</p><p><b>主机名：</b>${esc(l.hostname||'')}</p><p><b>DNS 解析：</b>${n.ok?'正常':'失败'} · ${esc((n.addresses||[]).join(', '))} · ${n.latency_ms||'—'}ms</p><p><b>Ping 目标：</b>${esc(p.host||'')} · 发送 ${p.sent||0} · 丢失 ${p.lost||0}</p>${d.speed?`<p><b>测速说明：</b>${esc(d.speed.note||d.speed.error||'')}</p>`:''}`;toast('网络检测完成')}catch(e){toast(e.message);$('net-detail').innerHTML=`<p class="empty">${esc(e.message)}</p>`}}
async function loadDashboard(){
  try{
    const d=await api('/api/dashboard/daily'),m=d.metrics||{},set=(id,value)=>{if($(id))$(id).textContent=value};
    set('dash-created',m.created??0);set('dash-resolved',m.resolved??0);set('dash-pending',m.pending??0);
    set('dash-overdue',m.overdue??0);set('dash-urgent',m.urgent??0);set('dash-avg',(m.avg_resolution_hours??0)+'h');
    set('dash-response-sla',(m.response_sla_percent??0)+'%');set('dash-resolution-sla',(m.resolution_sla_percent??0)+'%');
    set('dash-awaiting-confirmation',m.awaiting_confirmation??0);set('dash-csat',m.csat?`${m.csat}/5`:'0');
    set('dash-sla-risk',m.sla_at_risk??0);set('dash-reopen-rate',(m.reopen_rate??0)+'%');
    set('dash-gaps',m.knowledge_gaps??0);set('dash-low',m.low_knowledge_sources??0);
    const map=new Map([...(d.overdue_tickets||[]),...(d.urgent_tickets||[])].map(t=>[t.ticket_id,t]));
    $('dash-tickets').innerHTML=[...map.values()].map(t=>`<tr onclick="showTicket('${esc(t.ticket_id)}')"><td>${esc(t.ticket_id)}</td><td>${esc(t.title)}</td><td class="priority-${esc(t.priority)}">${esc(t.priority)}</td><td>${esc(t.assignee_nick||'未分配')}</td></tr>`).join('')||'<tr><td colspan="4">暂无风险工单</td></tr>';
    $('dash-repeated').innerHTML=(d.repeated_issues||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.category)}</td><td>${x.count}</td></tr>`).join('')||'<tr><td colspan="3">今日暂无重复故障</td></tr>';
    $('dash-knowledge-gaps').innerHTML=(d.knowledge_gaps||[]).map(x=>`<tr><td>${esc(x.question)}</td><td>${ticketLinkMarkup(x.ticket_id)}</td><td>${esc(x.updated_at)}</td></tr>`).join('')||'<tr><td colspan="3">暂无知识缺口</td></tr>';
    $('dash-low-sources').innerHTML=(d.low_knowledge_sources||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${x.success_count}</td><td>${x.fail_count}</td><td>${x.success_rate}%</td></tr>`).join('')||'<tr><td colspan="4">暂无低效知识</td></tr>';
    const demand=[...(d.top_services||[]).map(x=>['服务',x.service,x.count]),...(d.top_categories||[]).map(x=>['分类',x.category,x.count])];
    $('dash-service-demand').innerHTML=demand.map(x=>`<tr><td>${x[0]}</td><td>${esc(x[1])}</td><td>${x[2]}</td></tr>`).join('')||'<tr><td colspan="3">今日暂无数据</td></tr>';
    const ageLabels={'0_1d':'不足 1 天','1_3d':'1–3 天','3_7d':'3–7 天','over_7d':'超过 7 天'},workload=[...(d.assignee_load||[]).map(x=>['负责人',x.assignee,x.count]),...Object.entries(d.backlog_age||{}).map(([key,count])=>['积压龄期',ageLabels[key]||key,count])];
    $('dash-workload').innerHTML=workload.map(x=>`<tr><td>${x[0]}</td><td>${esc(x[1])}</td><td>${x[2]}</td></tr>`).join('')||'<tr><td colspan="3">当前没有积压</td></tr>';
  }catch(e){toast(e.message,'error')}
}
// 页面初始化、按需加载和定时刷新由 console-shell.js 统一调度。
